import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/RandomThoughts.html","title":"RandomThoughts","lang":"en-US","frontmatter":{},"git":{"createdTime":1640402155000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":4}]},"readingTime":{"minutes":2.66,"words":798},"filePathRelative":"RandomThoughts.md"}`),a={name:`RandomThoughts.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="randomthoughts" tabindex="-1"><a class="header-anchor" href="#randomthoughts"><span>RandomThoughts</span></a></h1><p>karino2のパーソナルWikiの公開部分。</p><p>公開用の雑多なメモを書いておく<a href="./サブWiki.html">サブWiki</a>を、RandomThoughtsという名前で作って公開している。ようするに現在あなたが見ているこのWikiの事。</p><ul><li>公開先URL <a href="https://karino2.github.io/RandomThoughts/Home" target="_blank" rel="noopener noreferrer">Home - RandomThoughts</a></li></ul><p>最近は<a href="./VuePress.html">VuePress</a>で公開している。</p><h2 id="本は書籍、をつけない事に" tabindex="-1"><a class="header-anchor" href="#本は書籍、をつけない事に"><span>本は書籍、をつけない事に</span></a></h2><p>当初は、本のWikiNameは書籍で始めて、スクリプトで<a href="./書籍.html">書籍</a>のページを生成していたのだが、 これがリンクを書くのが意外とかったるいのとバックリンクを実装したので別に書籍へのリンクを貼ればおおむね用は足りる、 という事で、今後は本も書籍をつけない事にする。</p><p>これまでの本にはついているが、歴史的事情という事で。</p><h2 id="randomthoughtsのvuepress化" tabindex="-1"><a class="header-anchor" href="#randomthoughtsのvuepress化"><span>RandomThoughtsのVuePress化</span></a></h2><p>RandomThoughtsを<a href="./VuePress.html">VuePress</a>に乗り換えた時のメモ。</p><p><a href="https://github.com/karino2/RandomThoughts" target="_blank" rel="noopener noreferrer">karino2/RandomThoughts: Wiki repository for random thoughts</a>のレポジトリで行った作業のメモ。</p><p>prism.jsでのmfgのシンタックスハイライトの対応をしたので、<a href="./RandomThoughts.html">RandomThoughts</a>もそれに対応したい。 いい機会なのでJekyllの<a href="./GitWiki.html">GitWiki</a>からVuePressに乗り換える方向で考えてみる。</p><ul><li><a href="https://theme-hope.vuejs.press/guide/layout/sidebar.html#string-format" target="_blank" rel="noopener noreferrer">Sidebar - vuepress-theme-hope</a> Recentsはこの辺で頑張る</li><li><a href="https://github.com/spencerwooo/vuepress-markdown-it-wikilink" target="_blank" rel="noopener noreferrer">spencerwooo/vuepress-markdown-it-wikilink: Wikimedia-style links for VuePress using the markdown-it parser</a> wikilinkはこれを試してみたい</li></ul><h3 id="作業メモ" tabindex="-1"><a class="header-anchor" href="#作業メモ"><span>作業メモ</span></a></h3><p>まず以下を実行。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ npm init</span>
<span class="line">$ npm install -D vuepress@next</span>
<span class="line">$ npm install -D @vuepress/bundler-vite@next @vuepress/theme-default@next</span>
<span class="line">$ npm install -D sass-embedded</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>最後はドキュメントに書いてないけどなんか必要（テンプレートを入れると勝手に入るからその手順の人はいらないらしい）</p><p>次にwiki_srcをそのまま扱う方向で作業してみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ mkdir wiki_src/.vuepress</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>あとはGetting Startedに従ってconfig.jsを作りnpm runを書く（名前は<code>wiki_src:dev</code>と<code>wiki_src:build</code>にして、パスもwiki_srcにしておく)</p><p>これで、とりあえずdevで<code>http://localhost:8080/Home.html</code>にはアクセス出来た。</p><h3 id="別のマシンでのセットアップ" tabindex="-1"><a class="header-anchor" href="#別のマシンでのセットアップ"><span>別のマシンでのセットアップ</span></a></h3><p>viteが古いとかいろいろ言われたので</p><ul><li>package.jsonからdevDependenciesでvuepress系を削除</li><li>package-lock.jsonを削除</li><li>node_modulesを削除</li></ul><p>をやってから上記のnpm installをやった。あとtheme-hopeが内と言われたので、以下を実行した。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ npm install -D vuepress-theme-hope  --legacy-peer-deps</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>なお最後のオプションはprimsjsのバージョンがvuepressの指定するバージョンと違うとか言われたから。</p><p>これでインストールが出来た。</p><h3 id="実行" tabindex="-1"><a class="header-anchor" href="#実行"><span>実行</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ cd scirpts</span>
<span class="line">$ server_all.sh</span>
<span class="line">$ cd ..</span>
<span class="line">$ npm run wiki2:dev</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これでアクセス出来た。</p><h3 id="wikilink対応" tabindex="-1"><a class="header-anchor" href="#wikilink対応"><span>WikiLink対応</span></a></h3><p>とりあえず<a href="https://github.com/spencerwooo/vuepress-markdown-it-wikilink" target="_blank" rel="noopener noreferrer">spencerwooo/vuepress-markdown-it-wikilink: Wikimedia-style links for VuePress using the markdown-it parser</a>を試してみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ npm install -D vuepress-markdown-it-wikilink</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>なんかそれっぽくconfig.jsを書いてみたが動かない。</p><p>buildの方をしたらエラーメッセージを吐いてくれた！</p><p>mdの方にリンクの中にタグと解釈される文字列が含まれていたせいだったので直したが、それでもwikilinkは有効にならない。</p><p>どうもこれはv1向けのプラグインっぽいなぁ。</p><p>単なるmarkdown-itのプラグインを手で呼ぶかなぁ。</p><p><a href="./TeFWiki.html">TeFWiki</a>はjekyllの制約でリンクパターンをカスタマイズしていたので、以下を使ってたので同じのを使ってみる。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ npm i -D @kwvanderlinde/markdown-it-wikilinks</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>optionsは<a href="./TeFWiki.html">TeFWiki</a>のものと同じので、以下で動いた。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">import wikilinks from &#39;@kwvanderlinde/markdown-it-wikilinks&#39;</span>
<span class="line"></span>
<span class="line">export default defineUserConfig({</span>
<span class="line">    bundler: viteBundler(),</span>
<span class="line">    theme: defaultTheme(),</span>
<span class="line">    extendsMarkdown: md =&gt; {</span>
<span class="line">        md.use(wikilinks(options))</span>
<span class="line">    },</span>
<span class="line">})</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>いやぁ、これは苦戦した。v1とv2で微妙に変わってて、ポイントとしては、markdownプロパティではなくextendsMarkdownを直接書く、という事と、 extendじゃなくてextendsに変わってる事（三単現のs…）。</p><p>これで無事動いた。</p><h3 id="日本語リンクが動かない" tabindex="-1"><a class="header-anchor" href="#日本語リンクが動かない"><span>日本語リンクが動かない</span></a></h3><p>これではいくつかの日本語の正規化の問題が正しく動かない。 例えば<a href="./【書籍】今を生きる思想、ジョン・ロールズ.html">【書籍】今を生きる思想、ジョン・ロールズ</a>などが辿れない。</p><p>これは以下に相当する処理が無いからだ。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">    encoded = urllib.parse.quote(unicodedata.normalize(&#39;NFC&#39;, original), safe=&#39;&#39;)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>とりあえずforkしたgithubを作り直してそれを使うようにしておこう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">npm install -D --save https://github.com/karino2/markdown-it-wikilinks.git#normalize_nfc_for_filename</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="タイトルとnavbar" tabindex="-1"><a class="header-anchor" href="#タイトルとnavbar"><span>タイトルとnavbar</span></a></h2><p>トップに戻る方法が無いとデバッグが面倒なので以下を追加。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">    theme: defaultTheme({</span>
<span class="line">      navbar: [</span>
<span class="line">        {text: &quot;Home&quot;, link: &quot;/Home.html&quot;}</span>
<span class="line">    ]</span>
<span class="line">    }),</span>
<span class="line">    title: &quot;RandomThoughts&quot;,</span>
<span class="line">    description: &quot;公開用Wiki、雑多なジャンルのメモを全部入れておく所&quot;,</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="ファイル名をh1に" tabindex="-1"><a class="header-anchor" href="#ファイル名をh1に"><span>ファイル名をH1に</span></a></h2><p>VuePressでやる方法がわからなかったので、シェルスクリプトで先頭に挟む事にする。</p><h2 id="recents" tabindex="-1"><a class="header-anchor" href="#recents"><span>Recents</span></a></h2><p>シェルスクリプトでgitを叩いて作ったrecentsを、以下の形のjsファイルに整形して出力し、recents.jsという名前にして.vuepressフォルダに置き、</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> recents <span class="token operator">=</span> <span class="token punctuation">[</span></span>
<span class="line"> <span class="token punctuation">{</span><span class="token literal-property property">text</span><span class="token operator">:</span> <span class="token string">&quot;Recents:&quot;</span><span class="token punctuation">,</span></span>
<span class="line">   <span class="token literal-property property">children</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">     <span class="token punctuation">{</span><span class="token literal-property property">link</span><span class="token operator">:</span> <span class="token string">&quot;Hoge.html&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">text</span><span class="token operator">:</span> <span class="token string">&quot;Hoge&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">     <span class="token punctuation">{</span><span class="token literal-property property">link</span><span class="token operator">:</span> <span class="token string">&quot;Ika.html&quot;</span><span class="token punctuation">,</span> <span class="token literal-property property">text</span><span class="token operator">:</span> <span class="token string">&quot;Ika&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">   <span class="token operator">...</span></span>
<span class="line">   <span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>config.jsを以下のようにした。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">import { recents } from &#39;./recents.js&#39;</span>
<span class="line"></span>
<span class="line">export default defineUserConfig({</span>
<span class="line">    theme: defaultTheme({</span>
<span class="line">      sidebar: recents,</span>
<span class="line">       ...</span>
<span class="line">    })</span>
<span class="line">})</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>git logで時間をとってsortしているが、GitHub Actionsのcheckoutアクションではlog情報が無いっぽいので、 recents.jsを作るスクリプトはローカルで定時でpushするスクリプトの方で動かしている。</p><h2 id="google-search-consoleのsite-verification" tabindex="-1"><a class="header-anchor" href="#google-search-consoleのsite-verification"><span>Google Search ConsoleのSite verification</span></a></h2><p>これまではhtmlファイル置くのにしていたが、htmlのheadにタグを置く形に変更する。</p><ol><li>Google Search Consoleの設定に行く</li><li>Ownership VerificationのHTML tagの所に行き、内容をコピー</li><li>config.jsに以下を追加(contentは2でコピーした値)</li></ol><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">    head: [</span>
<span class="line">      [&#39;meta&#39;, { name: &#39;google-site-verification&#39;, content: &#39;XXX_SOME_ID_XXX&#39; }]</span>
<span class="line">    ],</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="themeをhopeに変更" tabindex="-1"><a class="header-anchor" href="#themeをhopeに変更"><span>themeをhopeに変更</span></a></h2><p>何故かnpm installの例が載ってないけれど、普通にnpm installで平気だった。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$  npm install -D vuepress-theme-hope@latest</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>デフォルトのhighlighterがshikiになっちゃうのでprismに変更。 ついでにTaskListもenableにしておく。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> hopeTheme <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&quot;vuepress-theme-hope&quot;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">default</span> <span class="token function">defineUserConfig</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">theme</span><span class="token operator">:</span> <span class="token function">hopeTheme</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">      <span class="token comment">// navbarとかsidebarとかhomeはdefaultThemeと同じ内容なので割愛</span></span>
<span class="line">      <span class="token literal-property property">markdown</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token literal-property property">highlighter</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">          <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&quot;prismjs&quot;</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token literal-property property">tasklist</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token comment">//...</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>かなりいい感じになった。</p><h3 id="バックリンクの実装" tabindex="-1"><a class="header-anchor" href="#バックリンクの実装"><span>バックリンクの実装</span></a></h3><p><a href="./Wikiのリンクを扱うシェルスクリプト.html">Wikiのリンクを扱うシェルスクリプト</a>を元にjsonを生成して、それをcomponents/Backlink.vueからロードして書く感じにした。</p><ol><li>wiki2/.vuepress/components/backlinkData.js にバックリンク情報のjsonを生成(公開する定期実行スクリプトの一部にgen_backlinkdata.shを作って実行）</li><li>wiki2/.vuepress/components/Backlinks.vue からこのjsをロードしてレンダリング</li><li>wiki2/client.jsにBacklinks.vueを実行するコードを追加</li></ol><p>詳細は以下のコミットを参照。</p><ul><li><a href="https://github.com/karino2/RandomThoughts/commit/533d73cc0efddee4376a3de195fb595eb1673c53" target="_blank" rel="noopener noreferrer">Backlinkの実装 · karino2/RandomThoughts@533d73c</a></li><li><a href="https://github.com/karino2/RandomThoughts/commit/12403a114bdfdf41a9a063e5e6811d276d85c47c" target="_blank" rel="noopener noreferrer">日本語のリンクがuri encodeされて来てしまう事があるのでdecodeを挟む（バックリンク） · karino2/RandomThoughts@12403a1</a></li></ul><p>これで出来たが間に大きな余白が出るので少し調整。</p><p><a href="https://github.com/karino2/RandomThoughts/commit/711298d6fedde474c692238962b29002ad9dfb22" target="_blank" rel="noopener noreferrer">バックリンクの上の余白を無くすべく、LayoutのpageBottomに移動 · karino2/RandomThoughts@711298d</a></p><p>ついでにprevとnextも消す。</p><p><a href="https://github.com/karino2/RandomThoughts/commit/a96de5c9538d718d11893451fdfab07627503ef9" target="_blank" rel="noopener noreferrer">Recentsのprevとnextは使わないので消す。 · karino2/RandomThoughts@a96de5c</a></p><p>いい感じになった。</p><h2 id="math-support" tabindex="-1"><a class="header-anchor" href="#math-support"><span>Math support</span></a></h2><p><a href="./TeFWiki.html">TeFWiki</a>に数式サポートを入れているので、RandomThoughtsの公開の方にも数式を入れる。 プラグインもあるっぽいが、まぁmarkdown-itを既にconfig.jsで使っているので、ここに<a href="https://github.com/microsoft/vscode-markdown-it-katex/tree/main" target="_blank" rel="noopener noreferrer">microsoft/vscode-markdown-it-katex: Add Math to your Markdown with a KaTeX plugin for Markdown-it</a>を足す。</p><p><a href="https://github.com/karino2/RandomThoughts/commit/1961d4cb1d5f5bd46748f62983a179a5c4ce448e" target="_blank" rel="noopener noreferrer">math support. · karino2/RandomThoughts@1961d4c</a></p>`,85)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};